// Normalize Telegram and the private n8n chat into one request.
const incoming = $input.first().json;
const message = incoming.message;
const isTelegram = message?.chat?.id !== undefined;
if (isTelegram && message.from?.is_bot) return [];
const source = isTelegram ? 'telegram' : 'chat';
const chatId = isTelegram ? String(message.chat.id) : '';
const threadId = isTelegram ? (message.message_thread_id ?? null) : null;
const senderId = isTelegram ? String(message.from?.id ?? chatId) : '';
const chatInput = String(isTelegram ? (message.text ?? message.caption ?? '') : (incoming.chatInput ?? '')).trim();
const sessionId = isTelegram
  ? `books:telegram:${chatId}:${threadId ?? 0}:${senderId}`
  : `books:chat:${String(incoming.sessionId ?? $execution.id)}`;
const commandMatch = chatInput.match(/^\/([a-z]+)(?:@\w+)?(?:\s+([\s\S]*))?$/i);
const command = (commandMatch?.[1] ?? '').toLowerCase();
const commandArgument = (commandMatch?.[2] ?? '').trim();
const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
let route = 'agent';
let statsCategory = 'tous';
let output = '';
const question = normalize(chatInput)
  .replace(/^(?:bonjour|salut|bonsoir)\s+/, '')
  .replace(/^(?:(?:est ce que )?tu peux|peux tu|pourrais tu)\s+(?:me )?(?:dire |donner )?/, '')
  .replace(/^(?:dis moi|donne moi|affiche(?: moi)?)\s+/, '')
  .replace(/\s+(?:stp|svp|s il te plait|merci)$/, '');
const categoryFor = noun => /roman/.test(noun) ? 'romans' : /manga/.test(noun) ? 'mangas'
  : /comic/.test(noun) ? 'comics' : /^(?:bd|bandes dessinees?)$/.test(noun) ? 'bd' : 'tous';
const noun = '(livres?|ouvrages?|romans?|mangas?|comics?|bd|bandes dessinees?)';
const scope = '(?: (?:en tout|au total))?(?: dans (?:ma|la) (?:bibliotheque|collection))?(?: (?:en tout|au total))?';
const countPatterns = [
  `(?:j ai|je possede) combien de ${noun}`,
  `combien de ${noun}(?: (?:ai je|j ai|que j ai|je possede|est ce que j ai))?`,
  `combien (?:j ai|ai je|je possede|est ce que j ai) de ${noun}`,
  `(?:quel est )?(?:le |mon )?(?:nombre(?: total)?|total) (?:de |de mes |des )${noun}(?: (?:que j ai|que je possede))?`,
];
for (const pattern of countPatterns) {
  const match = question.match(new RegExp(`^(?:${pattern})${scope}$`));
  if (!command && match) { route = 'stats'; statsCategory = categoryFor(match[1]); break; }
}
if (!command && /^(?:mes statistiques|(?:les )?statistiques(?: globales| de ma (?:bibliotheque|collection))?|quel est le total de ma (?:bibliotheque|collection))$/.test(question)) route = 'stats';
if (command === 'stats' || command === 'total') {
  route = 'stats';
  if (commandArgument) {
    const selected = normalize(commandArgument);
    if (/^(?:livres?|ouvrages?|romans?|mangas?|comics?|bd|bandes dessinees?|tous|tout)$/.test(selected)) statsCategory = categoryFor(selected);
    else output = 'Utilise /stats, /stats mangas, /stats comics, /stats bd ou /stats romans.';
  }
} else if (command === 'serie' || command === 'chercher') {
  route = command;
  if (!commandArgument) output = command === 'serie'
    ? 'Indique le titre : /serie Toriko'
    : 'Indique un titre, un auteur ou un genre : /chercher Dune';
} else if (command === 'start' || command === 'help') {
  output = 'Je peux te conseiller des lectures et consulter ta bibliothèque de BD et de romans.\n\n'
    + '• J’ai combien de livres ?\n• Combien de tomes de Toriko me manque-t-il ?\n'
    + '• Conseille-moi trois romans que je possède et n’ai pas encore lus.\n\n'
    + 'Commandes directes :\n/stats : statistiques\n/serie Toriko : bilan d’une série\n/chercher Dune : recherche\n\n'
    + 'Pour les tomes manquants, je connais les quantités enregistrées ; les numéros exacts ne figurent pas dans ces tables.';
} else if (command) {
  output = 'Commande inconnue. Utilise /help pour les exemples, ou écris ta question normalement.';
}
if (!chatInput) output = 'Envoie-moi un message écrit. Les messages vocaux nécessitent une transcription qui n’est pas configurée ici.';
return [{ json: {
  source, chatId, threadId, sessionId, chatInput, command, commandArgument,
  route, statsCategory, needsLibrary: !output, output,
} }];

// Read each complete table once; keep the catalog outside the model prompt.
const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const normalize = value => clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const unique = values => [...new Set(values.filter(value => value !== null && value !== ''))];
const isOwnedStatus = status => /^possede(?:e|s)?(?:\s|$)/.test(normalize(status));
const parseCount = value => {
  if (value === null || value === undefined || value === '') return null;
  const text = String(value).replace(/[\s\u00a0\u202f]/g, '').replace(',', '.');
  if (!/^\d+(?:\.0+)?$/.test(text)) return null;
  const number = Number(text);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
};
const categoryFor = value => {
  const category = normalize(value);
  if (/manga/.test(category)) return 'mangas';
  if (/comic/.test(category)) return 'comics';
  if (/^(?:bd|bandes? dessinees?|franco belge)$/.test(category)) return 'bd';
  if (category === 'autre' || category === 'autres') return 'autres';
  return 'non_classes';
};
const catalog = [];
const sources = {};
const quality = { repeatedRows: 0, missingIds: 0, invalidRows: 0, counterConflicts: 0, unknownOwnedCounts: 0 };

for (const [support, nodeName] of [['bd', 'Read BD'], ['roman', 'Read Roman']]) {
  const items = $(nodeName).all();
  const failed = items.some(item => item.error || item.json?.error
    || (Object.hasOwn(item.json ?? {}, 'chatInput') && !Object.hasOwn(item.json ?? {}, 'titre')));
  if (failed) {
    sources[support] = { available: false, rows: 0, records: 0, error: `La table ${support === 'bd' ? 'BD' : 'Roman'} n’a pas pu être lue.` };
    continue;
  }
  const groups = new Map();
  let rowCount = 0;
  for (const item of items) {
    const row = item.json ?? {};
    if (Object.keys(row).length === 0) continue; // n8n's empty-table placeholder.
    if (!clean(row.titre)) { quality.invalidRows++; continue; }
    rowCount++;
    let key = clean(row.id_unique);
    if (!key) {
      quality.missingIds++;
      // Do not collapse different editions merely because they share a title.
      key = clean(row.id) ? `row:${row.id}` : `row:${JSON.stringify(row)}`;
    }
    if (!groups.has(key)) groups.set(key, []);
    else quality.repeatedRows++;
    groups.get(key).push(row);
  }
  sources[support] = { available: true, rows: rowCount, records: groups.size };
  for (const [id, rows] of groups) {
    const statuses = unique(rows.map(row => clean(row.statut)));
    const ownedRows = rows.filter(row => isOwnedStatus(row.statut));
    const preferred = ownedRows[0] ?? rows[0];
    const record = {
      id, support, titre: clean(preferred.titre).slice(0, 300),
      statut: unique((ownedRows.length ? ownedRows : rows).map(row => clean(row.statut))).join(' / ').slice(0, 200),
      possession: ownedRows.length ? true : null,
      lecture: 'inconnue', liste_souhait: false, anomalies: [],
    };
    if (support === 'bd') {
      const categories = unique(rows.map(row => clean(row.categorie)));
      record.categorie = categories.length === 1 ? categoryFor(categories[0]) : 'non_classes';
      record.categorie_source = categories.join(' / ').slice(0, 160);
      for (const field of ['albums_possedes', 'albums_lus', 'albums_manquants', 'albums_non_possedes_lu']) {
        const raw = rows.map(row => row[field]).filter(value => value !== null && value !== undefined && clean(value) !== '');
        const values = unique(raw.map(parseCount));
        const invalid = raw.some(value => parseCount(value) === null);
        record[field] = !invalid && values.length === 1 ? values[0] : null;
        if (values.length > 1 || invalid) {
          record.anomalies.push(`Valeurs contradictoires ou invalides : ${field}.`);
          quality.counterConflicts++;
        }
      }
      if (record.albums_possedes !== null) record.possession = record.albums_possedes > 0;
      if (ownedRows.length && record.albums_possedes === null) quality.unknownOwnedCounts++;
      if (record.albums_possedes === 0 && ownedRows.length) record.anomalies.push('Statut possédé mais nombre de tomes possédés égal à zéro.');
      if (record.albums_possedes > 0 && statuses.some(status => /^non possede/.test(normalize(status)))) record.anomalies.push('Le nombre de tomes possédés contredit un statut non possédé.');
      record.liste_souhait = record.possession !== true && statuses.some(status => /souhait/.test(normalize(status)));
      if (record.possession === true && record.albums_lus !== null) {
        record.lecture = record.albums_lus === 0 ? 'non_lu'
          : record.albums_lus >= record.albums_possedes ? 'lu' : 'en_cours';
      }
    } else {
      record.categorie = 'romans';
      record.auteur = unique(rows.map(row => clean(row.auteur))).join(' / ').slice(0, 250);
      record.genre = unique(rows.map(row => clean(row.genre))).join(' / ').slice(0, 250);
      record.possession = ownedRows.length > 0;
      record.liste_souhait = !record.possession && statuses.some(status => /souhait/.test(normalize(status)));
      const reading = unique((ownedRows.length ? ownedRows : rows).map(row => {
        const status = normalize(row.statut);
        if (/\bnon lu\b/.test(status)) return 'non_lu';
        if (/\bje lis\b/.test(status)) return 'en_cours';
        if (/\blu\b/.test(status)) return 'lu';
        return 'inconnue';
      }));
      record.lecture = reading.length === 1 ? reading[0] : 'statuts_mixtes';
      // Different editions may share one id_unique; count the title once.
      record.editions_regroupees = unique(rows.map(row => [clean(row.editeur), clean(row.annee_sortie), clean(row.nb_pages)].join('|'))).length;
    }
    record.searchTitle = normalize(record.titre);
    record.searchKey = normalize([record.titre, record.auteur, record.genre, record.categorie_source].filter(Boolean).join(' '));
    catalog.push(record);
  }
}
catalog.sort((a, b) => a.titre.localeCompare(b.titre, 'fr') || a.id.localeCompare(b.id));
const albums = { mangas: 0, comics: 0, bd: 0, autres: 0, non_classes: 0 };
const roman = { possedes: 0, lus: 0, non_lus: 0, en_cours: 0, lecture_non_classee: 0, souhaits: 0 };
let ownedSeries = 0;
let missingStarted = 0;
let missingUnknown = 0;
let conflictOwned = false;
for (const book of catalog) {
  if (book.support === 'bd') {
    if (book.albums_possedes === null && book.anomalies.some(value => value.includes('albums_possedes'))) conflictOwned = true;
    if (book.possession !== true) continue;
    ownedSeries++;
    if (book.albums_possedes !== null) albums[book.categorie] += book.albums_possedes;
    if (book.albums_manquants !== null) missingStarted += book.albums_manquants;
    else missingUnknown++;
  } else {
    if (book.liste_souhait) roman.souhaits++;
    if (!book.possession) continue;
    roman.possedes++;
    const key = { lu: 'lus', non_lu: 'non_lus', en_cours: 'en_cours' }[book.lecture] ?? 'lecture_non_classee';
    roman[key]++;
  }
}
const albumsTotal = Object.values(albums).reduce((sum, value) => sum + value, 0);
const complete = sources.bd.available && sources.roman.available && quality.invalidRows === 0;
const reliable = complete && quality.unknownOwnedCounts === 0 && !conflictOwned;
const stats = {
  statut: reliable ? 'ok' : 'incomplet',
  total_livres_possedes: reliable ? albumsTotal + roman.possedes : null,
  albums: sources.bd.available ? { ...albums, total_connu: albumsTotal, series_possedees: ownedSeries,
    tomes_manquants_series_possedees: missingUnknown ? null : missingStarted } : null,
  romans: sources.roman.available ? roman : null,
  portee: 'Albums possédés de BD + titres distincts possédés de Roman. Un id_unique n’est compté qu’une fois dans chaque table. Les éditions de romans partageant cet identifiant sont regroupées. Livres audio non inclus.',
  quality,
};
const output = reliable
  ? `Ta bibliothèque contient ${stats.total_livres_possedes.toLocaleString('fr-FR')} livres enregistrés comme possédés :\n`
    + `• Mangas : ${albums.mangas.toLocaleString('fr-FR')} tomes\n`
    + `• Comics : ${albums.comics.toLocaleString('fr-FR')} albums\n`
    + `• BD franco-belges : ${albums.bd.toLocaleString('fr-FR')} albums\n`
    + `• Autres catégories de la table BD : ${albums.autres.toLocaleString('fr-FR')} albums\n`
    + (albums.non_classes ? `• Catégorie non classée : ${albums.non_classes.toLocaleString('fr-FR')} albums\n` : '')
    + `• Romans : ${roman.possedes.toLocaleString('fr-FR')} titres distincts\n\n`
    + `Romans possédés : ${roman.lus} lus, ${roman.non_lus} non lus, ${roman.en_cours} en cours`
    + (roman.lecture_non_classee ? `, ${roman.lecture_non_classee} au statut de lecture non classé` : '')
    + `.\nRomans en liste de souhait uniquement : ${roman.souhaits}.\n`
    + (quality.repeatedRows ? 'Les identifiants répétés sont regroupés ; plusieurs éditions portant le même identifiant comptent pour un seul titre.\n' : '')
    + 'Périmètre : tables BD et Roman, hors livres audio.'
  : 'Je ne peux pas donner un total fiable : '
    + Object.values(sources).filter(source => !source.available).map(source => source.error).join(' ')
    + (quality.invalidRows || quality.unknownOwnedCounts || conflictOwned ? ' Certaines lignes ou quantités possédées sont incomplètes ou contradictoires.' : '')
    + ' Vérifie les tables BD et Roman dans cette exécution n8n.';
return [{ json: { catalog, sources, stats, statsOutput: output } }];

// Pure local search over all records; expose a small result page and exact match counts.
function searchLibrary(library, input) {
  const normalize = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const support = normalize(input.support || 'tous');
  const state = normalize(input.etat || 'tous');
  const allowedSupports = ['tous', 'bd', 'roman', 'romans', 'mangas', 'comics', 'franco belge', 'autres'];
  const allowedStates = ['tous', 'possedes', 'non lus', 'lus', 'en cours', 'souhaits', 'manquants'];
  if (!allowedSupports.includes(support) || !allowedStates.includes(state)) return {
    statut: 'parametre_invalide', message: 'support : tous, bd, roman, mangas, comics, franco_belge, autres. etat : tous, possedes, non_lus, lus, en_cours, souhaits, manquants.',
  };
  const rawSearch = String(input.recherche ?? '').trim();
  const key = normalize(rawSearch);
  if (rawSearch && !key) return { statut: 'recherche_invalide', message: 'Indique un titre, un auteur ou un genre.' };
  if (key.length > 250) return { statut: 'recherche_trop_longue', message: 'Recherche par quelques mots du titre, de l’auteur ou du genre.' };
  const wantedSources = support === 'roman' || support === 'romans' ? ['roman'] : support === 'tous' ? ['bd', 'roman'] : ['bd'];
  const unavailable = wantedSources.filter(source => !library.sources[source].available);
  const partial = unavailable.length > 0 || library.stats.quality.invalidRows > 0;
  if (unavailable.length === wantedSources.length) return { statut: 'indisponible', message: 'La lecture des tables nécessaires a échoué. Aucune conclusion sur la présence d’un livre n’est possible.' };
  const words = key.split(' ').filter(Boolean);
  let matches = library.catalog.filter(book => {
    if (!wantedSources.includes(book.support)) return false;
    if (['mangas', 'comics', 'autres'].includes(support) && book.categorie !== support) return false;
    if (support === 'franco belge' && book.categorie !== 'bd') return false;
    if (state === 'possedes' && book.possession !== true) return false;
    if (state === 'non lus' && !(book.possession === true && ['non_lu', 'en_cours'].includes(book.lecture))) return false;
    if (state === 'lus' && !(book.possession === true && book.lecture === 'lu')) return false;
    if (state === 'en cours' && !(book.possession === true && book.lecture === 'en_cours')) return false;
    if (state === 'souhaits' && !book.liste_souhait) return false;
    if (state === 'manquants' && !(book.support === 'bd' && book.possession === true && book.albums_manquants > 0)) return false;
    const haystack = input.titleOnly ? book.searchTitle : book.searchKey;
    return words.every(word => haystack.includes(word));
  });
  // A complete title takes priority; broader matches remain available on a shorter query.
  const exact = key ? matches.filter(book => book.searchTitle === key) : [];
  if (exact.length) matches = exact;
  const view = book => {
    const base = {
      titre: book.titre, support: book.support, categorie: book.categorie,
      possession: book.possession, lecture: book.lecture, liste_souhait: book.liste_souhait,
    };
    if (book.support === 'bd') Object.assign(base, {
      albums_possedes: book.albums_possedes, albums_lus: book.albums_lus,
      albums_manquants: book.albums_manquants, albums_non_possedes_lu: book.albums_non_possedes_lu,
    });
    else Object.assign(base, { auteur: book.auteur, genre: book.genre, editions_regroupees: book.editions_regroupees });
    if (book.anomalies.length) base.anomalies = book.anomalies;
    return base;
  };
  const matchingBd = matches.filter(book => book.support === 'bd');
  const ownedBd = matchingBd.filter(book => book.possession === true);
  const sumKnown = (rows, field) => rows.some(book => book[field] === null)
    ? null : rows.reduce((sum, book) => sum + book[field], 0);
  return {
    statut: partial ? 'partiel' : 'ok',
    recherche: rawSearch, correspondance_exacte: exact.length > 0,
    correspondances: matches.length, resultats_limites: matches.length > 8,
    total_albums_possedes_correspondants: sumKnown(matchingBd, 'albums_possedes'),
    total_romans_possedes_correspondants: matches.filter(book => book.support === 'roman' && book.possession === true).length,
    total_tomes_manquants_series_possedees_correspondantes: sumKnown(ownedBd, 'albums_manquants'),
    livres: matches.slice(0, 8).map(view),
    remarque: 'Les quantités viennent des tables. Les numéros exacts des tomes manquants ne sont pas disponibles. '
      + (partial ? 'Une table ou certaines lignes n’ont pas pu être lues : résultats et totaux partiels. ' : '')
      + (matches.length > 8 ? 'Seuls 8 résultats sont affichés ; précise le titre pour voir les autres.' : ''),
  };
}

function formatSearch(result) {
  if (!['ok', 'partiel'].includes(result.statut)) return result.message;
  if (!result.livres.length) return result.statut === 'partiel'
    ? 'Aucun résultat dans les données disponibles, mais une table n’a pas pu être lue.'
    : 'Aucun résultat pour cette recherche dans les tables BD et Roman. Essaie un mot distinctif du titre.';
  const number = value => value === null ? 'non renseigné' : value.toLocaleString('fr-FR');
  const lines = result.livres.map(book => book.support === 'bd'
    ? `• ${book.titre}\n  Tomes possédés : ${number(book.albums_possedes)} ; lus enregistrés : ${number(book.albums_lus)} ; manquants indiqués : ${number(book.albums_manquants)}.`
      + (book.anomalies?.length ? '\n  Certaines valeurs sont contradictoires et doivent être vérifiées.' : '')
    : `• ${book.titre}${book.auteur ? ` — ${book.auteur}` : ''}\n  ${book.possession ? 'Possédé' : book.liste_souhait ? 'Liste de souhait' : 'Non enregistré comme possédé'} ; lecture : ${{ lu: 'lu', non_lu: 'non lu', en_cours: 'en cours', statuts_mixtes: 'statuts différents selon les éditions', inconnue: 'non renseignée' }[book.lecture]}.`);
  return `${result.correspondances} résultat(s)${result.correspondance_exacte ? ' pour ce titre exact' : ''}.\n\n`
    + lines.join('\n\n') + '\n\n' + result.remarque;
}

const request = $('Prepare request').first().json;
const library = $input.first().json;
let output = '';
if (request.route === 'stats') {
  output = library.statsOutput;
  if (library.stats.statut === 'ok' && request.statsCategory !== 'tous') {
    const category = request.statsCategory;
    const count = category === 'romans' ? library.stats.romans.possedes : library.stats.albums[category];
    const label = { mangas: 'tomes de mangas', comics: 'albums de comics', bd: 'albums de BD franco-belge', romans: 'titres distincts dans la table Roman' }[category];
    output = `Tu possèdes ${count.toLocaleString('fr-FR')} ${label}, après regroupement des identifiants répétés.`;
  }
} else if (request.route === 'serie' || request.route === 'chercher') {
  output = formatSearch(searchLibrary(library, {
    recherche: request.commandArgument, support: request.route === 'serie' ? 'bd' : 'tous',
    etat: 'tous', titleOnly: request.route === 'serie',
  }));
} else if (!library.sources.bd.available && !library.sources.roman.available) {
  output = 'Je ne peux pas consulter ta bibliothèque pour le moment. Vérifie les tables BD et Roman et leur accès depuis ce workflow.';
}
// Only the question reaches the agent; tools read the catalog from Prepare library.
return [{ json: { chatInput: request.chatInput, needsAgent: !output, output } }];

